-- Phase 2 business operations foundation.
alter table public.inventory add column if not exists branch_id uuid references public.branches(id) on delete set null;
alter table public.repairs add column if not exists branch_id uuid references public.branches(id) on delete set null;
alter table public.sales add column if not exists branch_id uuid references public.branches(id) on delete set null;
alter table public.financial_transactions add column if not exists branch_id uuid references public.branches(id) on delete set null;
alter table public.repairs add column if not exists engineer_id uuid references public.engineers(id) on delete set null;
alter table public.repairs add column if not exists assigned_at timestamptz;
create index if not exists inventory_branch_idx on public.inventory(branch_id);
create index if not exists repairs_branch_idx on public.repairs(branch_id);
create index if not exists repairs_engineer_idx on public.repairs(engineer_id,created_at desc);
create index if not exists sales_branch_idx on public.sales(branch_id);
create index if not exists financial_transactions_branch_idx on public.financial_transactions(branch_id);
update public.inventory i set branch_id=b.id from public.branches b where i.branch_id is null and b.company_id=i.company_id and b.is_main=true;
update public.repairs r set branch_id=b.id from public.branches b where r.branch_id is null and b.company_id=r.company_id and b.is_main=true;
update public.sales s set branch_id=b.id from public.branches b where s.branch_id is null and b.company_id=s.company_id and b.is_main=true;
update public.financial_transactions f set branch_id=b.id from public.branches b where f.branch_id is null and b.company_id=f.company_id and b.is_main=true;
create table if not exists public.repair_assignments (id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,repair_id uuid not null references public.repairs(id) on delete cascade,engineer_id uuid not null references public.engineers(id) on delete restrict,assigned_by uuid references auth.users(id),assigned_at timestamptz not null default now(),unassigned_at timestamptz,notes text);
create index if not exists repair_assignments_repair_idx on public.repair_assignments(repair_id,assigned_at desc);
create index if not exists repair_assignments_engineer_idx on public.repair_assignments(engineer_id,assigned_at desc);
alter table public.repair_assignments enable row level security;
drop policy if exists repair_assignments_select on public.repair_assignments;
create policy repair_assignments_select on public.repair_assignments for select to authenticated using(company_id=public.get_my_company_id());
drop policy if exists repair_assignments_insert on public.repair_assignments;
create policy repair_assignments_insert on public.repair_assignments for insert to authenticated with check(company_id=public.get_my_company_id());
grant select,insert on public.repair_assignments to authenticated;
create or replace function public.assign_repair_engineer(p_repair_id uuid,p_engineer_id uuid,p_notes text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare c uuid; eid uuid; aid uuid; begin c:=public.get_my_company_id(); if c is null then raise exception 'Company not found'; end if; select company_id into eid from public.engineers where id=p_engineer_id; if eid is null or eid<>c then raise exception 'Engineer not found'; end if; if not exists(select 1 from public.repairs where id=p_repair_id and company_id=c) then raise exception 'Repair not found'; end if; update public.repair_assignments set unassigned_at=now() where repair_id=p_repair_id and company_id=c and unassigned_at is null; update public.repairs set engineer_id=p_engineer_id,assigned_at=now(),technician=(select name from public.engineers where id=p_engineer_id) where id=p_repair_id and company_id=c; insert into public.repair_assignments(company_id,repair_id,engineer_id,assigned_by,notes) values(c,p_repair_id,p_engineer_id,auth.uid(),p_notes) returning id into aid; return aid; end; $$;
revoke all on function public.assign_repair_engineer(uuid,uuid,text) from public,anon;
grant execute on function public.assign_repair_engineer(uuid,uuid,text) to authenticated;
create table if not exists public.engineer_part_ledger (id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid references public.branches(id) on delete set null,engineer_id uuid not null references public.engineers(id) on delete restrict,inventory_id uuid not null references public.inventory(id) on delete restrict,repair_id uuid references public.repairs(id) on delete set null,movement_type text not null check(movement_type in ('issued','used','returned','adjustment')),quantity integer not null check(quantity>0),unit_cost numeric(14,2) not null default 0 check(unit_cost>=0),notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create index if not exists engineer_part_ledger_engineer_idx on public.engineer_part_ledger(engineer_id,created_at desc);
alter table public.engineer_part_ledger enable row level security;
drop policy if exists engineer_part_ledger_select on public.engineer_part_ledger;
create policy engineer_part_ledger_select on public.engineer_part_ledger for select to authenticated using(company_id=public.get_my_company_id());
grant select on public.engineer_part_ledger to authenticated;
create table if not exists public.invoices (id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid references public.branches(id) on delete set null,invoice_number text not null,customer_id uuid references public.customers(id) on delete set null,repair_id uuid references public.repairs(id) on delete set null,sale_id uuid references public.sales(id) on delete set null,status text not null default 'issued' check(status in ('draft','issued','part_paid','paid','void')),subtotal numeric(14,2) not null default 0,discount numeric(14,2) not null default 0,total numeric(14,2) not null default 0,issued_at timestamptz not null default now(),due_at timestamptz,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(company_id,invoice_number));
create table if not exists public.invoice_items (id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.invoices(id) on delete cascade,description text not null,quantity numeric(12,2) not null default 1 check(quantity>0),unit_price numeric(14,2) not null default 0 check(unit_price>=0),line_total numeric generated always as(quantity*unit_price) stored);
create table if not exists public.customer_debt_ledger (id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid references public.branches(id) on delete set null,customer_id uuid not null references public.customers(id) on delete restrict,invoice_id uuid references public.invoices(id) on delete set null,source_type text not null check(source_type in('invoice','repair','sale','payment','adjustment')),source_id uuid,debit numeric(14,2) not null default 0 check(debit>=0),credit numeric(14,2) not null default 0 check(credit>=0),notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),check(debit>0 or credit>0));
create index if not exists invoices_customer_idx on public.invoices(customer_id,issued_at desc);
create index if not exists customer_debt_customer_idx on public.customer_debt_ledger(customer_id,created_at desc);
alter table public.invoices enable row level security; alter table public.invoice_items enable row level security; alter table public.customer_debt_ledger enable row level security;
drop policy if exists invoices_select on public.invoices; create policy invoices_select on public.invoices for select to authenticated using(company_id=public.get_my_company_id());
drop policy if exists invoices_insert on public.invoices; create policy invoices_insert on public.invoices for insert to authenticated with check(company_id=public.get_my_company_id());
drop policy if exists invoice_items_select on public.invoice_items; create policy invoice_items_select on public.invoice_items for select to authenticated using(exists(select 1 from public.invoices i where i.id=invoice_id and i.company_id=public.get_my_company_id()));
drop policy if exists invoice_items_insert on public.invoice_items; create policy invoice_items_insert on public.invoice_items for insert to authenticated with check(exists(select 1 from public.invoices i where i.id=invoice_id and i.company_id=public.get_my_company_id()));
drop policy if exists customer_debt_select on public.customer_debt_ledger; create policy customer_debt_select on public.customer_debt_ledger for select to authenticated using(company_id=public.get_my_company_id());
drop policy if exists customer_debt_insert on public.customer_debt_ledger; create policy customer_debt_insert on public.customer_debt_ledger for insert to authenticated with check(company_id=public.get_my_company_id());
grant select,insert on public.invoices,public.invoice_items,public.customer_debt_ledger to authenticated;
create or replace function public.get_customer_balances() returns table(customer_id uuid,customer_name text,phone text,debit numeric,credit numeric,balance numeric) language sql security invoker set search_path=public as $$ select c.id,c.full_name,c.phone,coalesce(sum(d.debit),0),coalesce(sum(d.credit),0),coalesce(sum(d.debit-d.credit),0) from public.customers c left join public.customer_debt_ledger d on d.customer_id=c.id and d.company_id=public.get_my_company_id() where c.company_id=public.get_my_company_id() group by c.id,c.full_name,c.phone having coalesce(sum(d.debit-d.credit),0)<>0 order by coalesce(sum(d.debit-d.credit),0) desc; $$;
grant execute on function public.get_customer_balances() to authenticated;
create table if not exists public.role_permissions(role text not null,permission text not null,allowed boolean not null default true,primary key(role,permission));
insert into public.role_permissions(role,permission,allowed) values ('owner','*',true),('branch_manager','inventory.manage',true),('branch_manager','repairs.manage',true),('branch_manager','sales.manage',true),('branch_manager','reports.view',true),('branch_manager','engineers.manage',true),('branch_manager','audit.view',true),('technician','repairs.manage',true),('technician','inventory.issue',true),('technician','inventory.return',true),('front_desk','customers.manage',true),('front_desk','repairs.manage',true),('front_desk','sales.manage',true),('front_desk','payments.manage',true),('front_desk','inventory.view',true) on conflict(role,permission) do update set allowed=excluded.allowed;
alter table public.role_permissions enable row level security;
drop policy if exists role_permissions_select on public.role_permissions; create policy role_permissions_select on public.role_permissions for select to authenticated using(true);
grant select on public.role_permissions to authenticated;
create or replace function public.has_permission(p_permission text) returns boolean language sql security invoker set search_path=public as $$ select exists(select 1 from public.profiles p join public.role_permissions rp on rp.role=p.role where p.id=auth.uid() and p.is_active=true and (rp.permission='*' or(rp.permission=p_permission and rp.allowed=true))); $$;
grant execute on function public.has_permission(text) to authenticated;
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid references public.branches(id) on delete set null,actor_id uuid references auth.users(id) on delete set null,action text not null,entity_type text not null,entity_id uuid,old_data jsonb,new_data jsonb,metadata jsonb,created_at timestamptz not null default now());
create index if not exists audit_logs_company_idx on public.audit_logs(company_id,created_at desc);
alter table public.audit_logs enable row level security;
drop policy if exists audit_logs_select on public.audit_logs; create policy audit_logs_select on public.audit_logs for select to authenticated using(company_id=public.get_my_company_id() and public.has_permission('audit.view'));
grant select on public.audit_logs to authenticated;
create or replace function public.write_audit_log(p_action text,p_entity_type text,p_entity_id uuid default null,p_old jsonb default null,p_new jsonb default null,p_metadata jsonb default null) returns uuid language plpgsql security definer set search_path=public as $$ declare c uuid; aid uuid; begin c:=public.get_my_company_id(); if c is null then raise exception 'Company not found'; end if; insert into public.audit_logs(company_id,actor_id,action,entity_type,entity_id,old_data,new_data,metadata) values(c,auth.uid(),p_action,p_entity_type,p_entity_id,p_old,p_new,p_metadata) returning id into aid; return aid; end; $$;
revoke all on function public.write_audit_log(text,text,uuid,jsonb,jsonb,jsonb) from public,anon;
grant execute on function public.write_audit_log(text,text,uuid,jsonb,jsonb,jsonb) to authenticated;
create table if not exists public.inventory_transfers(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,inventory_id uuid not null references public.inventory(id) on delete restrict,from_branch_id uuid not null references public.branches(id),to_branch_id uuid not null references public.branches(id),quantity integer not null check(quantity>0),status text not null default 'completed' check(status in('completed','cancelled')),notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),check(from_branch_id<>to_branch_id));
create index if not exists inventory_transfers_company_idx on public.inventory_transfers(company_id,created_at desc); alter table public.inventory_transfers enable row level security; drop policy if exists inventory_transfers_select on public.inventory_transfers; create policy inventory_transfers_select on public.inventory_transfers for select to authenticated using(company_id=public.get_my_company_id()); grant select on public.inventory_transfers to authenticated;
create or replace view public.engineer_performance_summary with(security_invoker=true) as select e.id engineer_id,e.company_id,e.name,e.status,count(r.id) total_repairs,count(r.id) filter(where lower(coalesce(r.status,'')) in('completed','ready','collected')) completed_repairs,count(r.id) filter(where lower(coalesce(r.status,'')) not in('completed','ready','collected')) active_repairs,coalesce(sum(coalesce(r.final_cost,r.estimated_cost,0)) filter(where lower(coalesce(r.status,'')) in('completed','ready','collected')),0) repair_revenue from public.engineers e left join public.repairs r on r.engineer_id=e.id and r.company_id=e.company_id group by e.id,e.company_id,e.name,e.status;
grant select on public.engineer_performance_summary to authenticated;
create or replace view public.inventory_report_summary with(security_invoker=true) as select company_id,branch_id,count(*) sku_count,coalesce(sum(quantity),0) units,coalesce(sum(quantity*coalesce(cost_price,0)),0) stock_cost,count(*) filter(where quantity=0) out_of_stock,count(*) filter(where quantity<=minimum_stock) low_stock from public.inventory where company_id=public.get_my_company_id() group by company_id,branch_id;
grant select on public.inventory_report_summary to authenticated;
create or replace view public.repair_report_summary with(security_invoker=true) as select company_id,branch_id,count(*) total_repairs,count(*) filter(where lower(coalesce(status,'')) in('completed','ready','collected')) completed,count(*) filter(where lower(coalesce(status,'')) not in('completed','ready','collected')) active,coalesce(sum(coalesce(final_cost,estimated_cost,0)),0) revenue from public.repairs where company_id=public.get_my_company_id() group by company_id,branch_id;
grant select on public.repair_report_summary to authenticated;
create or replace view public.sales_report_summary with(security_invoker=true) as select company_id,branch_id,count(*) total_sales,coalesce(sum(total),0) revenue from public.sales where company_id=public.get_my_company_id() group by company_id,branch_id;
grant select on public.sales_report_summary to authenticated;
